#!/usr/bin/env bash
#
# Refresh the published OpenAPI documents from a Gerrit checkout's build outputs.
#
# gerrit-openapi is a distribution point, not a source of truth: every document here is
# a byte-for-byte copy of a Gerrit build output. Run this to re-sync after a spec change,
# then review the diff, commit, and -- at a release -- tag (e.g. v3.15.0) so consumers
# can pin an immutable spec.
#
# The core spec is generated by the gerrit_rules_openapi ruleset wired into Gerrit's
# //openapi package (the migration off the in-tree //tools/openapi pipeline), so the
# gerrit checkout must be on openapi_integration (or a branch where it is merged), and
# its MODULE.bazel local_path_override must resolve gerrit_rules_openapi.
#
# Usage: ./update.sh [path-to-gerrit-checkout]     (default: ../gerrit6)
set -euo pipefail
cd "$(dirname "$0")"

SRC=${1:-../gerrit6}
[ -d "$SRC" ] || { echo "error: gerrit checkout not found: $SRC" >&2; exit 1; }
SRC=$(cd "$SRC" && pwd)

# core per-area slices (target //openapi:openapi_<name>_json)
DOMAINS=(access accounts changes config flow groups plugins projects)
# plugins with their own OpenAPI document: "<package-dir> <target-name>"
# NOTE: these still reference the plugin packages' own openapi targets; they are
# orthogonal to the core migration and must be retargeted when the plugin side
# moves onto the ruleset's openapi_plugin_spec.
PLUGINS=(
  "checks checks_openapi_json"
  "code-owners code_owners_openapi_json"
)

echo "1/4 build the OpenAPI documents in $SRC"
# openapi_json also drives the miner's worklist report (openapi-overrides-report.json),
# which the statistics step reads; name it so it is always present in bazel-bin.
TARGETS="//openapi:openapi_json //openapi:openapi-overrides-report.json"
for d in "${DOMAINS[@]}"; do TARGETS="$TARGETS //openapi:openapi_${d}_json"; done
for entry in "${PLUGINS[@]}"; do
  set -- $entry
  TARGETS="$TARGETS //plugins/$1:$2"
done
( cd "$SRC" && bazel build $TARGETS 2>&1 | tail -1 )

BIN="$SRC/bazel-bin"
echo "2/4 copy build outputs into the published tree"
cp "$BIN/openapi/all-domain-openapi.generated.json" core/openapi.json
for d in "${DOMAINS[@]}"; do
  cp "$BIN/openapi/${d}-openapi.generated.json" "core/domains/${d}.json"
done
for entry in "${PLUGINS[@]}"; do
  set -- $entry
  mkdir -p "plugins/$1"
  cp "$BIN/plugins/$1/$2.generated.json" "plugins/$1/openapi.json"
done
# bazel outputs are read-only; the published copies are normal files.
chmod -R u+w core plugins

echo "3/4 sanity: the domain slices must partition the monolith"
python3 - <<'PY'
import glob, json, sys
mono = len(json.load(open("core/openapi.json")).get("paths", {}))
areas = sum(len(json.load(open(f)).get("paths", {})) for f in glob.glob("core/domains/*.json"))
ver = json.load(open("core/openapi.json")).get("info", {}).get("version")
ok = mono == areas
print(f"   core paths={mono}  sum(core/domains)={areas}  version={ver}  "
      f"[{'partition OK' if ok else 'PARTITION MISMATCH'}]")
sys.exit(0 if ok else 1)
PY

echo "4/4 refresh statistics (rendered from the ruleset's stats tool -- one source, no recompute)"
# The stats tool now lives in the gerrit_rules_openapi ruleset (lifted out of core's
# //tools/openapi/py); it emits JSON and gen_stats.py only formats it into STATISTICS.md
# + accumulates the per-release history. $SRC/../gerrit_rules_openapi mirrors the
# local_path_override the gerrit checkout uses.
SNAP=$(mktemp)
python3 "$SRC/../gerrit_rules_openapi/extractor/py/stats_report.py" --json \
  "$BIN/openapi/all-domain-openapi.generated.json" \
  "$BIN/openapi/openapi-overrides-report.json" > "$SNAP"
python3 tools/gen_stats.py --stats "$SNAP"
rm -f "$SNAP"

echo
echo "done. Review the diff and commit; at a release, tag to match info.version:"
git status --short core plugins STATISTICS.md stats || true
